contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val, address _log) public payable {
        require(_log != address(0));

        // First successful SetMinSum on a fresh contract.
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;

        // SetLogFile must succeed afterwards because the contract is still uninitialized.
        c.SetLogFile(_log); if (__ESBMC_reverted()) return;

        // SetLogFile should not change MinSum.
        assert(c.MinSum() == _val);
    }
}

